#pragma once

#include <controller_interface/chainable_controller_interface.hpp>
#include <realtime_tools/realtime_buffer.hpp>
#include <safety_position_controller/collision_checker.hpp>
#include <sensor_msgs/msg/joint_state.hpp>
#include <std_msgs/msg/bool.hpp>
#include <std_msgs/msg/float64_multi_array.hpp>
#include <std_msgs/msg/string.hpp>
#include <std_srvs/srv/set_bool.hpp>
#include <urdf_model/joint.h>

#include <hector_ros_controllers_msgs/msg/safety_position_controller_status.hpp>

// auto-generated by generate_parameter_library
#include <hector_ros_controllers/safety_position_controller_parameters.hpp>

namespace safety_position_controller
{
using CmdType = std_msgs::msg::Float64MultiArray;
/**
 * @brief Chained-only safety controller.
 *
 * - Enforces joint limits (pos/vel), optional unwrapping for continuous joints.
 * - Optional self-collision check via CollisionChecker (URDF + SRDF).
 * - Optional current-limit control (stiff/compliant) toggled by service.
 *   - Assumes actuator uses current values as limits in position control mode.
 * - Subscribes to SRDF on "robot_description_semantic" (transient local).
 */
class SafetyPositionController final : public controller_interface::ChainableControllerInterface
{
public:
  /// @brief Ctor; controller is chainable-only by design.
  SafetyPositionController();

  /**
   * @brief Initialize parameters, SRDF subscriber, and (optionally) collision checker.
   * @return CallbackReturn::SUCCESS on success, else ::ERROR
   */
  controller_interface::CallbackReturn on_init() override;

  /**
   * @brief Configure with current parameters; waits for SRDF if needed, builds CC.
   * @param previous_state lifecycle state (unused)
   * @return SUCCESS/ERROR
   */
  controller_interface::CallbackReturn
  on_configure( const rclcpp_lifecycle::State &previous_state ) override;

  /**
   * @brief Activate controller; validates interfaces, updates params, prepares limits.
   * Reloads dynamic parameters. -> Controllers must be deactivated/reactivated to apply changes!
   * @param previous_state lifecycle state (unused)
   * @return SUCCESS/ERROR
   */
  controller_interface::CallbackReturn
  on_activate( const rclcpp_lifecycle::State &previous_state ) override;

  /**
   * @brief Deactivate controller (no special action).
   * @param previous_state lifecycle state (unused)
   * @return SUCCESS
   */
  controller_interface::CallbackReturn
  on_deactivate( const rclcpp_lifecycle::State &previous_state ) override;

  /**
   * @brief Request command interfaces.
   * - Always: <joint>/position
   * - Optional: <joint>/current (if current-limit control enabled)
   */
  controller_interface::InterfaceConfiguration command_interface_configuration() const override;

  /**
   * @brief Request state interfaces.
   * - All non-fixed joints: <joint>/position (needed for CC and unwrapping)
   */
  controller_interface::InterfaceConfiguration state_interface_configuration() const override;

  /**
   * @brief Export per-joint reference interfaces (position) for chaining.
   * @return vector of CommandInterface referencing internal reference buffers
   */
  std::vector<hardware_interface::CommandInterface> on_export_reference_interfaces() override;

  /**
   * @brief Chained-only: no direct subscribers, just return OK.
   */
  controller_interface::return_type
  update_reference_from_subscribers( const rclcpp::Time &time,
                                     const rclcpp::Duration &period ) override;

  /**
   * @brief Main step: read states → enforce limits → (optional) block-if-too-far
   * → (optional) set current limits → (optional) self-collision check → write commands.
   * @return OK on success; ERROR if read/write failed
   */
  controller_interface::return_type
  update_and_write_commands( const rclcpp::Time &time, const rclcpp::Duration &period ) override;

  /**
   * @brief Enable/disable chained mode.
   * @note Controller is intended to run chained; non-chained falls back to hold.
   */
  bool on_set_chained_mode( bool chained_mode ) override;

private:
  /// @brief Joint type classification used for limit/unwrap logic.
  enum class JointType { CONTINUOUS, REVOLUTE_BOUNDED, PRISMATIC_BOUNDED, FIXED, OTHER };

  /**
   * @brief Read current joint positions for configured joints.
   * @return true if all reads succeeded
   */
  bool read_current_positions();

  /**
   * @brief Write per-joint position commands (NaN entries are skipped).
   * @param commands commanded positions (size == params_.joints.size())
   * @return true if all writes succeeded (for non-NaN entries)
   */
  bool write_position_commands( const std::vector<double> &commands );

  /**
   * @brief Apply unwrap/clamp rules to references → fill cmd_positions_.
   */
  void enforce_limits();

  /**
   * @brief Limit per-cycle motion by vel_limit/update_rate, scaled by
   * block_velocity_scaling and the distance-based scaling factor.
   * @param distance_scale [0,1] factor from distance-based scaling (1.0 = full speed, 0.0 = hold)
   */
  void apply_velocity_limits( double distance_scale );

  /**
   * @brief Write current-limit commands (stiff/compliant) if enabled.
   * @return true if all writes succeed
   */
  bool write_current_limits();

  /**
   * @brief Unwrap target angle to the nearest equivalent around current.
   * @param current current angle [rad]
   * @param target target angle (wrapped) [rad]
   * @return unwrapped target near current
   */
  static double unwrap_to_nearest( double current, double target );

  /**
   * Compute the signed shortest distance between two revolute joint angles.
   *
   * @param value_a  Start angle (rad)
   * @param value_b  Target angle (rad)
   * @return Signed minimal angular difference in [-π, π].
   *         Positive → turn left (CCW), Negative → turn right (CW).
   */
  static double get_signed_distance( double value_a, double value_b );

  /**
   * @brief Clamp value to [lower, upper] (with validity checks); logs on clamp.
   * @param i joint index in params_.joints
   * @param value requested value
   * @param bypass_active if true, applies tolerance extension to limits
   * @return clamped value
   */
  double clamp( size_t i, double value, bool bypass_active = false ) const;

  /**
   * @brief Parse URDF, collect joint names (non-fixed) and limits for params_.joints.
   * @param urdf_xml URDF as XML string
   * @return true on success
   */
  bool parse_urdf_and_fill_joint_info( const std::string &urdf_xml );

  /**
   * @brief Map params_.joints to all_joint_names_ indices for state interface reads.
   * We have len(all_joint_names_) state interfaces, need to find indices for params_.joints.
   * @return true if all indices were found
   */
  bool gather_joint_indices();

  /**
   * @brief Wait for SRDF on "robot_description_semantic" (bounded attempts).
   * @return true if received before timeout
   */
  bool wait_for_srdf();

  /**
   * @brief Compute the directional derivative of collision distance along the
   * commanded motion direction for a given gradient vector.
   * @param gradient dd/dv vector (size model_.nv) from CollisionChecker
   * @return dot product (positive = moving away from collision)
   */
  double compute_directional_derivative( const Eigen::VectorXd &gradient ) const;

  void publish_debug_joint_state_in();
  void publish_debug_joint_state_out( const std::vector<double> &positions );
  void update_debug_publishers( bool enable );
  void publish_status();

  // ---- Configuration / mode ----
  bool is_chained_ = true;         ///< chained-only controller (hold if false)
  bool in_compliant_mode_ = false; ///< selects compliant vs. stiff current limits

  // ---- E-stop ----
  std::atomic<bool> estop_active_{ false };  ///< last requested E-stop state
  std::atomic<bool> estop_engaged_{ false }; ///< actually engaged in update loop

  // ---- Safety bypass (for folded arm positions etc.) ----
  std::atomic<bool> safety_bypass_active_{
      false }; ///< when true, collision checks and strict limits are relaxed
  rclcpp::TimerBase::SharedPtr safety_bypass_timer_; ///< auto re-enables safety checks after timeout
  rclcpp::Service<std_srvs::srv::SetBool>::SharedPtr
      bypass_safety_checks_service_; ///< service to toggle bypass

  // ---- Interface bookkeeping ----
  std::vector<int> joint_index_; ///< index in all_joint_names per params_.joints

  // ---- URDF-based joint info ----
  std::vector<JointType> kinds_;                       // in order of params_.joints
  std::vector<bool> has_limits_;                       // in order of params_.joints
  std::vector<double> lower_limits_;                   // in order of params_.joints
  std::vector<double> upper_limits_;                   // in order of params_.joints
  std::vector<double> velocity_limits_;                // in order of params_.joints
  std::vector<double> max_allowed_distance_per_cycle_; // in order of params_.joints

  // ---- Collision checking context ----
  std::vector<std::string> all_joint_names_;             ///< all non-fixed joint names (state)
  std::unordered_map<std::string, double> cc_positions_; ///< name→position map for CC
  std::unique_ptr<CollisionChecker> collision_checker_;  ///< optional self-collision checker
  std::string srdf_;                                     ///< SRDF XML (semantic)
  bool srdf_received_ = false;                           ///< latched SRDF received
  double last_min_distance_{
      std::numeric_limits<double>::max() }; ///< previous cycle's min collision distance

  // ---- Directional collision scaling ----
  std::vector<int> joint_v_index_; ///< maps controlled joint index → pinocchio velocity-space index
  std::vector<CollisionResult::PairInfo>
      last_safety_zone_pairs_; ///< safety-zone pairs from previous collision check
  double last_distance_scale_{ 1.0 };
  double last_effective_scale_{ 1.0 };
  double last_worst_directional_derivative_{ std::numeric_limits<double>::max() };

  // ---- Command/state buffers (aligned with params_.joints) ----
  std::vector<double> cmd_positions_;     ///< post-enforcement commands
  std::vector<double> current_positions_; ///< latest measured positions
  bool on_hold_{ false };                 ///< non-chained fallback
  std::vector<double> hold_positions_;    ///< positions to hold when not chained

  // ---- Parameters ----
  std::shared_ptr<ParamListener> param_listener_;
  std::shared_ptr<rclcpp::ParameterEventHandler> param_subscriber_;
  std::shared_ptr<rclcpp::ParameterCallbackHandle> cb_handle_debug_pubs_;
  Params params_;

  // ---- ROS I/F ----
  rclcpp::Service<std_srvs::srv::SetBool>::SharedPtr
      enforce_current_limits_service_; ///< toggles compliant mode
  rclcpp::Subscription<std_msgs::msg::String>::SharedPtr
      semantic_description_sub_; ///< SRDF (transient local)

  // Non-chained command input
  realtime_tools::RealtimeBuffer<std::shared_ptr<CmdType>> rt_command_ptr_;
  rclcpp::Subscription<CmdType>::SharedPtr joints_command_subscriber_;

  // E-stop input
  rclcpp::Subscription<std_msgs::msg::Bool>::SharedPtr estop_subscriber_;

  // Debug JointState publishers
  rclcpp::Publisher<sensor_msgs::msg::JointState>::SharedPtr debug_in_js_pub_;
  rclcpp::Publisher<sensor_msgs::msg::JointState>::SharedPtr debug_out_js_pub_;

  // Status publisher (latched)
  rclcpp::Publisher<hector_ros_controllers_msgs::msg::SafetyPositionControllerStatus>::SharedPtr status_pub_;

  static constexpr int throttle_logging_msg = 2000; ///< ms; throttle for WARN/ERROR logs
};

} // namespace safety_position_controller
